// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address target, uint256 mintedAmount) public {
        vm.assume(target != address(0));
        vm.assume(target != address(this));
        vm.assume(mintedAmount > 0);

        vm.prank(address(this));
        c.mintToken(target, mintedAmount);

        uint256 ownerBal = c.balanceOf(address(this));
        uint256 targetBal = c.balanceOf(target);
        uint256 topTwoSum = ownerBal > targetBal ? ownerBal + targetBal : targetBal + ownerBal;

        assertTrue(c.totalSupply() >= topTwoSum);
    }
}
